import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework._FWOmmqu.js";const g=JSON.parse('{"title":"Live Chat","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/live-chat"}]]},"headers":[],"relativePath":"user-guide/live-chat.md","filePath":"user-guide/live-chat.md","lastUpdated":1789601521000}'),o={name:"user-guide/live-chat.md"};function s(r,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="live-chat" tabindex="-1">Live Chat <a class="header-anchor" href="#live-chat" aria-label="Permalink to &quot;Live Chat&quot;">​</a></h1><p>Install <strong>Live Chat</strong> from Marketplace (free). Open <strong>Communication → Live Chat</strong>.</p><h2 id="widget-setup" tabindex="-1">Widget setup <a class="header-anchor" href="#widget-setup" aria-label="Permalink to &quot;Widget setup&quot;">​</a></h2><ol><li>Open Live Chat and expand <strong>Widget settings</strong> (requires <code>live-chat.manage</code>).</li><li>Set greeting, branding (color, launcher text, position, header, logo), and optionally require name/email before chat starts.</li><li>Configure <strong>business hours</strong> (workspace timezone). Outside hours, visitors see the offline greeting and can leave a message when offline mode is enabled.</li><li>Optionally enable <strong>email notify agents</strong> for inbound/offline messages.</li><li>Copy the embed snippet onto your website (script loads from your EloSync API host).</li><li>Keep the widget <strong>Active</strong> so visitors can start conversations.</li></ol><p>Regenerating the public key invalidates existing embeds until you update the snippet.</p><h2 id="agent-inbox" tabindex="-1">Agent inbox <a class="header-anchor" href="#agent-inbox" aria-label="Permalink to &quot;Agent inbox&quot;">​</a></h2><ul><li>Conversation list on the left with filters: All, Unread, Mine, Unassigned, Open, Closed, Offline.</li><li>Thread, visitor details, and actions on the right.</li><li>Reply with <code>live-chat.reply</code>. Claim or assign with <code>live-chat.assign</code>. Close/reopen from the thread header.</li><li>Insert <strong>canned replies</strong> from the composer (manage canned replies in settings).</li><li>Search filters by visitor name, email, page URL, or message preview.</li><li>New visitor messages update in near-realtime when Echo/Reverb is connected (polling remains as fallback). Desktop/sound alerts play while the inbox is open.</li></ul><h2 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h2><p>Create departments under widget settings (<code>live-chat.manage</code>), assign agents, and set a default department on the widget for new conversations.</p><h2 id="leads" tabindex="-1">Leads <a class="header-anchor" href="#leads" aria-label="Permalink to &quot;Leads&quot;">​</a></h2><p>When <strong>Leads</strong> is installed:</p><ul><li>Search and link an existing lead, or create a new lead from the thread and auto-link it.</li><li>Unlink anytime. Linking requires <code>live-chat.reply</code> or <code>live-chat.manage</code> plus Leads access.</li></ul><h2 id="help-desk" tabindex="-1">Help Desk <a class="header-anchor" href="#help-desk" aria-label="Permalink to &quot;Help Desk&quot;">​</a></h2><p>When <strong>Help Desk</strong> is installed, escalate a conversation to a ticket from the thread (<code>live-chat.reply</code> plus Help Desk create permission). The conversation keeps a soft link to the ticket.</p><h2 id="moderation" tabindex="-1">Moderation <a class="header-anchor" href="#moderation" aria-label="Permalink to &quot;Moderation&quot;">​</a></h2><p>With <code>live-chat.manage</code>, ban a visitor from the thread. Banned visitors cannot start new sessions.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>New visitor messages create an in-app notification that opens <code>/live-chat?conversation={uuid}</code>. Optional email notify (widget setting) alerts agents when configured.</p>',18)])])}const m=t(o,[["render",s]]);export{g as __pageData,m as default};
